def default_config() -> dict:
    """Deep copy of DEFAULTS."""
    return json.loads(json.dumps(DEFAULTS))

class ConfigStore:
    """Hot-reloadable config: ``~/.hermes/continue_hook.json`` overrides defaults.

    Cached by mtime; a missing or malformed file silently falls back to
    defaults. Never raises.
    """

    def __init__(self, path: Path):
        self.path = path
        self._mtime: float | None = None
        self._cfg: dict | None = None

    def load(self) -> dict:
        mtime = None
        try:
            mtime = self.path.stat().st_mtime
        except OSError:
            pass
        if self._cfg is not None and mtime == self._mtime:
            return self._cfg
        cfg = default_config()
        try:
            user = json.loads(self.path.read_text(encoding="utf-8"))
            for k, v in user.items():
                if isinstance(v, dict) and isinstance(cfg.get(k), dict):
                    cfg[k].update(v)
                else:
                    cfg[k] = v
        except Exception:
            pass  # bad file → defaults (never crash the gateway)
        self._mtime, self._cfg = mtime, cfg
        return cfg

def _compile(patterns) -> re.Pattern:
    # A string is one pattern, not a list of characters: `"offer": "要不要我"`
    # used to be iterated per character and matched almost anything.
    if isinstance(patterns, str):
        patterns = [patterns]
    pats = [p for p in (patterns or []) if isinstance(p, str) and p]
    if not pats:
        return re.compile(r"(?!x)x")  # never-matching pattern
    # Case-insensitive: the English triggers are written lowercase, so without
    # this flag "Should I…" (the most common form — it starts the sentence) did
    # not match `should i` at all and only the trailing "?" caught it. The
    # Chinese patterns are unaffected.
    return re.compile("|".join(f"(?:{p})" for p in pats), re.S | re.IGNORECASE)

def _int(value: Any, fallback: int) -> int:
    """A config value as an int, never raising.

    ``max_nudges_per_turn: two`` must not turn every stop into
    ``error:ValueError`` — the documented behaviour is "fall back to defaults".
    """
    if isinstance(value, bool):
        return fallback
    if isinstance(value, int):
        return value
    try:
        return int(str(value).strip())
    except (TypeError, ValueError):
        return fallback

def strip_code_and_links(text: str) -> str:
    """Remove code blocks, inline code, links and URLs. Pure.

    Applied to the WHOLE reply before the closing window is taken. Doing it
    the other way round meant a fenced block whose closing ``` fell outside the
    last 240 characters left its "?" in place — and "the reply ends with a code
    block" is one of the most common shapes.
    """
    for pattern in (_CODE_BLOCK_RE, _INLINE_CODE_RE, _MARKDOWN_LINK_RE, _URL_RE):
        text = pattern.sub(" ", text)
    return text

def _first_trigger_hit(triggers: dict, tail: str) -> str | None:
    """The name of the first trigger pattern that matches, or None. Pure."""
    # ⚠ 这里是**唯一**决定「哪些 trigger 会被检查」的地方 —— 只在 triggers 配置里
    # 加一个键、不在这里登记，那个键永远不会生效（2026-10-29 实测：promise 加了配置
    # 却全量 no_trigger，就是因为漏了这一行）。
    #
    # ⚠ `promise` **故意不在这里**：它在 detect() 里已经用「剥掉代码块/引用后的窗口」
    # 单独判定过一次（并且排在 boundary 之前）。放进这个元组会让它在这里被
    # **原文 tail** 再判一遍 —— 2026-10-29 实测：代码块里的 `# TODO:` 正是这样
    # 二次命中的，明明前面已经用干净窗口排除了。
    for name in ("offer", "hand_off", "confirm_seek"):
        if _compile(triggers.get(name)).search(tail):
            return name
    return None

def detect(text: str, attempt: int, cfg: dict) -> tuple[bool, str]:
    """Return ``(should_nudge, reason_code)``. Pure transport layer.

    The per-turn cap is applied **after** the text is judged: whether a reply
    ends the turn is a property of the text, and the caller has to know it even
    once the cap is reached — otherwise the nudge chain never closes and that
    session stays muted for good.
    """
    if not text or not str(text).strip():
        return False, "empty"
    full = str(text).strip()
    stripped = strip_code_and_links(full)
    tail_chars = _int(cfg.get("tail_chars", 240), 240)
    tail = full[-tail_chars:]
    ex = cfg.get("exclusions", {})
    tr = cfg.get("triggers", {})
    trig_tail = _QUOTE_RE.sub("", tail)  # quoted mentions are not asks
    # ---------------------------------------------------------------------
    # `promise` 的判定顺序（2026-10-29 两轮红队各纠正一次，见下）
    #
    # 为什么 promise 要**先于** `boundary` 排除：
    #   真实收尾句「下一步我去查…有没有定价页和真实客户证言——那是该品类的
    #   **付费**证据…」被 boundary 的「付费」命中而整句放行。那是名词
    #   （"付费证据"），不是「我要去付款」—— 词表分不出来，加词表只会再漏。
    #
    # 但 `hard_boundary` **只能挡 promise 自己**，不能做全局早退：
    #   上一版把它放在 detect() 最顶端，于是它短路了 offer / hand_off /
    #   question_mark 全部触发。1422 条真实回复回放：1.3.5 nudge 28 (1.97%)，
    #   那一版 nudge 16 (1.13%) —— **被吞掉 12 条**，其中 6 条 question_mark、
    #   4 条 hand_off、3 条 offer。被吞的原句比如
    #   「要我现在就把这个加固做了吗？顺便说，上次发布很顺利。」（尾窗含「发布」）
    #   ⇒ 护栏从「拦太多」变成「几乎什么都不拦」。
    # ---------------------------------------------------------------------
    # ⚠ 必须用**剥掉代码块与引用**的 tail：`tail` 是原文，代码块里的
    # `# TODO: refactor` 会被当成承诺（2026-10-29 误伤实测，中英文各一条）。
    _promise_window = _QUOTE_RE.sub("", stripped[-tail_chars:])
    # 「下一步需要你…」不是承诺，是要用户给东西 —— 明确排除。
    _needs_user = re.search(
        r"下一步(要|需要)(你|您)|next step (needs|requires) (your|the user)|"
        r"next step is your|下一步(是)?(你|您)的?(决|定|选择|call)|"
        r"next step is blocked (on|by)|下一步(卡|阻塞)在",
        _promise_window,
    )
    # ⚠ `hard_boundary` 只否掉 **promise 这一条路**，随后继续走下面的
    # boundary / user_must / offer / hand_off / question_mark。
    _promise_hit = (not _needs_user) and bool(_compile(tr.get("promise")).search(_promise_window))
    if _promise_hit and (
        _compile(ex.get("boundary")).search(tail) or _compile(ex.get("user_must")).search(tail)
    ):
        # 承诺本身就是不可逆 / 对外 / 需要用户独有的东西 ⇒ 放行。
        #
        # ⚠ 2026-10-29 第三轮红队：`hard_boundary` 是 `boundary` 的**真子集**。
        # 曾经只用 hard_boundary 挡 promise，于是 boundary 原本拦得住的
        # `push` / `npm publish` / `merge into main` / `发到 npm` /
        # `rotate the production keys` 全漏 —— 22 条不可逆承诺 22 条被 nudge，
        # 其中 14 条是 1.3.5 曾经放行的。用更小的网取代更大的网 = 护栏回退。
        # ⇒ boundary 与 hard_boundary 取**并集**，hard_boundary 只做补充。
        return False, "boundary"
    if _promise_hit:
        if _int(attempt, 0) >= _int(cfg.get("max_nudges_per_turn", 2), 2):
            return False, "max_nudges"
        return True, "trigger:promise"
    if _compile(ex.get("boundary")).search(tail):
        return False, "boundary"
    if _compile(ex.get("user_must")).search(tail):
        return False, "user_must"
    # The closing window of the code-stripped text, so the "?" check only sees
    # punctuation that is actually prose.
    no_urls = _QUOTE_RE.sub("", stripped[-tail_chars:])
    name = _first_trigger_hit(tr, trig_tail)
    if name is not None:
        hit = f"trigger:{name}"
    elif tr.get("question_mark", True) and re.search(r"[？?]", no_urls):
        hit = "trigger:question_mark"
    else:
        # The turn ended cleanly — say so even when the cap is already reached.
        return False, "no_trigger"
    if _int(attempt, 0) >= _int(cfg.get("max_nudges_per_turn", 2), 2):
        return False, "max_nudges"
    return True, hit

def build_nudge(attempt: int, reason: str = "") -> str:
    if reason == "trigger:promise":
        return PROMISE_NUDGE_TEMPLATE.replace("{attempt}", str(attempt + 1))
    return NUDGE_TEMPLATE.replace("{attempt}", str(attempt + 1))

__all__ = [
    "Decision",
    "decide",
    "load_config",
    "log_event",
    "read_state",
    "write_state",
]

STATE_VERSION = 2

def default_config_path() -> Path:
    """Where the shared config lives (resolved per call, so HOME can move)."""
    return Path.home() / ".hermes" / "continue_hook.json"

def default_state_path() -> Path:
    return Path.home() / ".hermes" / "continue-hook-state.json"

def default_events_path() -> Path:
    return Path.home() / ".hermes" / "continue-hook-events.jsonl"

class Decision:
    """The verdict for one evaluation.

    A plain class rather than a dataclass: the core imports this file with
    ``importlib.util.spec_from_file_location`` and does not always register
    it in ``sys.modules`` — and ``@dataclass`` looks the module up there,
    which would make the import fail.
    """

    __slots__ = ("attempt", "reason", "should_nudge")

    def __init__(self, should_nudge: bool, reason: str, attempt: int = 0):
        self.should_nudge = should_nudge
        self.reason = reason
        self.attempt = attempt

    def __repr__(self) -> str:
        return (f"Decision(should_nudge={self.should_nudge!r}, "
                f"reason={self.reason!r}, attempt={self.attempt!r})")

    def to_json(self) -> dict[str, Any]:
        return {
            "should_nudge": self.should_nudge,
            "reason": self.reason,
            "attempt": self.attempt,
        }

def load_config(path: Path | str | None = None) -> dict[str, Any]:
    """Load the shared config; a missing or broken file falls back to defaults."""
    cfg_path = Path(path) if path else default_config_path()
    try:
        return ConfigStore(cfg_path).load()
    except Exception:
        return {}

def _empty_state() -> dict[str, Any]:
    return {"version": STATE_VERSION, "sessions": {}}

def read_state(path: Path | str | None = None) -> dict[str, Any]:
    """Read the state file, migrating the v1 flat layout to v2.

    v1: ``{"<session>": {"count": 1, "last_ts": 123}}``
    v2: ``{"version": 2, "sessions": {"<session>": {...}}}``
    """
    state_path = Path(path) if path else default_state_path()
    try:
        raw = json.loads(state_path.read_text(encoding="utf-8"))
    except Exception:
        return _empty_state()
    if not isinstance(raw, dict):
        return _empty_state()
    if raw.get("version") == STATE_VERSION and isinstance(raw.get("sessions"), dict):
        return raw
    # v1 migration: every top-level key that maps to an object is a session.
    sessions: dict[str, Any] = {}
    for key, value in raw.items():
        if isinstance(key, str) and isinstance(value, dict) and "count" in value:
            sessions[key] = {
                "count": int(value.get("count", 0)),
                "total": int(value.get("count", 0)),
                "last_ts": float(value.get("last_ts", 0.0)),
                "chain": False,
            }
    return {"version": STATE_VERSION, "sessions": sessions}

def write_state(state: dict[str, Any], path: Path | str | None = None) -> None:
    """Persist the state file. Never raises — losing state must not break a turn."""
    state_path = Path(path) if path else default_state_path()
    try:
        state_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        state_path.write_text(json.dumps(state, ensure_ascii=False), encoding="utf-8")
        try:
            state_path.chmod(0o600)
        except OSError:
            pass
    except Exception:
        pass

class _StateLock:
    """An advisory lock around the state file.

    Several hosts can fire hooks at the same moment (a user with two agents
    open, or two hosts in parallel). Without a lock the read-modify-write
    loses updates: the counters for one session overwrite another's, and the
    nudge caps stop holding.

    The lock is a separate ``.lock`` file, so the state file itself is never
    truncated while another process holds it. If locking is unavailable
    (Windows, exotic filesystems), the code still works — it just loses the
    guarantee.
    """

    def __init__(self, state_path: Path):
        self.path = Path(str(state_path) + ".lock")
        self._handle: Any = None

    def __enter__(self) -> _StateLock:
        try:
            import fcntl

            self.path.parent.mkdir(parents=True, exist_ok=True)
            self._handle = open(self.path, "a+")
            fcntl.flock(self._handle.fileno(), fcntl.LOCK_EX)
        except Exception:
            self._handle = None
        return self

    def __exit__(self, *exc: object) -> None:
        if self._handle is None:
            return
        try:
            import fcntl

            fcntl.flock(self._handle.fileno(), fcntl.LOCK_UN)
        except Exception:
            pass
        try:
            self._handle.close()
        except Exception:
            pass
        self._handle = None

def log_event(
    event: dict[str, Any],
    path: Path | str | None = None,
    *,
    snippet: bool = True,
) -> None:
    """Append one evaluation record. Never raises.

    The record can carry the tail of the reply, which is conversation content.
    ``snippet=False`` keeps the decision and drops the text; the file is written
    owner-only either way.
    """
    events_path = Path(path) if path else default_events_path()
    try:
        record = {"ts": time.strftime("%Y-%m-%d %H:%M:%S"), **event}
        if not snippet:
            record.pop("snippet", None)
        created_dir = not events_path.parent.exists()
        events_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        if created_dir:
            try:
                events_path.parent.chmod(0o700)
            except OSError:
                pass
        with open(events_path, "a", encoding="utf-8") as handle:
            handle.write(json.dumps(record, ensure_ascii=False) + "\n")
        try:
            events_path.chmod(0o600)
        except OSError:
            pass  # exotic filesystem; the file still works
    except Exception:
        pass

def _num(value: Any, fallback: float, *, integer: bool) -> float:
    """Coerce a config value, tolerating what people actually write.

    ``cooldown_seconds: 5m`` or ``max_nudges_per_turn: two`` used to raise
    inside the hook, which breaks the turn instead of falling back — the exact
    opposite of the documented fail-safe behaviour.
    """
    if isinstance(value, bool):
        return float(fallback)
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip().lower()
        multipliers = {"s": 1, "m": 60, "h": 3600}
        if text and text[-1] in multipliers and text[:-1].replace(".", "", 1).isdigit():
            return float(text[:-1]) * multipliers[text[-1]]
        try:
            return float(text)
        except ValueError:
            return float(fallback)
    return float(fallback)

STATE_TTL_SECONDS = 30 * 24 * 3600

def _prune_sessions(state: dict[str, Any], now: float | None = None) -> None:
    """Drop sessions we have not seen for a month.

    Without this the table grows forever, and a host that reuses a session id
    inherits whatever count the old session left behind.
    """
    sessions = state.get("sessions")
    if not isinstance(sessions, dict):
        return
    cutoff = (now if now is not None else time.time()) - STATE_TTL_SECONDS
    for name in [
        name
        for name, entry in sessions.items()
        if not isinstance(entry, dict)
        or _num(entry.get("last_ts", 0.0), 0.0, integer=False) < cutoff
    ]:
        sessions.pop(name, None)

def _session_entry(state: dict[str, Any], session_id: str) -> dict[str, Any]:
    sessions = state.setdefault("sessions", {})
    entry = sessions.get(session_id)
    if not isinstance(entry, dict):
        entry = {"count": 0, "total": 0, "last_ts": 0.0, "chain": False}
        sessions[session_id] = entry
    return entry

def close_chain(
    *,
    session_id: str,
    host: str,
    platform: str = "",
    state_path: Path | str | None = None,
    events_path: Path | str | None = None,
) -> None:
    """End this turn's nudge chain without nudging.

    A host that reports ``stop_hook_active`` is telling us it is already
    continuing because of a block we issued. That continuation ends *this*
    turn's chain, and the next user turn must start from zero.

    Skipping this call entirely — what the adapters used to do — left the
    per-turn counter raised, so ``max_nudges_per_turn: 2`` silently became a
    quota shared across user turns: the second turn spent the first turn's
    allowance and the third got nothing.
    """
    resolved = Path(state_path) if state_path else default_state_path()
    events = Path(events_path) if events_path else default_events_path()
    with _StateLock(resolved):
        state = read_state(resolved)
        entry = _session_entry(state, session_id)
        entry["count"] = 0
        entry["chain"] = False
        state["version"] = STATE_VERSION
        write_state(state, resolved)
    log_event(
        {
            "session": session_id,
            "host": host,
            "platform": platform,
            "decision": "skip",
            "reason": "chain_closed",
            "attempt": 0,
            "snippet": "",
        },
        events,
    )

def decide(
    text: str,
    *,
    session_id: str,
    host: str,
    config_path: Path | str | None = None,
    state_path: Path | str | None = None,
    events_path: Path | str | None = None,
    continued: bool = False,
    platform: str = "",
) -> Decision:
    """Decide whether to nudge, and record why.

    ``continued`` tells the service the host already forced this turn to
    continue (Claude Code / Codex / Copilot / Gemini / Qwen report it as
    ``stop_hook_active``). Hosts that do not report it can leave it ``False``:
    the chain is tracked in the state file either way.
    """
    # The documented kill switch, in one place so that every caller (plugin,
    # shell adapters, patch mode) honours it. The plugin mode used to ignore it.
    if os.environ.get("HERMES_CONTINUE_HOOK") == "0":
        log_event(
            {
                "session": session_id,
                "host": host,
                "platform": platform,
                "decision": "skip",
                "reason": "disabled_env",
                "attempt": 0,
                "snippet": "",
            },
            events_path,
        )
        return Decision(should_nudge=False, reason="disabled_env", attempt=0)

    cfg = load_config(config_path)
    # The config may redirect the log (a private directory, a read-only home).
    if (
        events_path is None
        and isinstance(cfg.get("events_path"), str)
        and cfg["events_path"].strip()
    ):
        events_path = Path(str(cfg["events_path"])).expanduser()
    # The whole read-modify-write happens under the lock: two hooks firing at
    # once must not overwrite each other's counters.
    state_path = Path(state_path) if state_path else default_state_path()
    with _StateLock(state_path):
        return _decide_locked(
            text,
            session_id=session_id,
            host=host,
            cfg=cfg,
            state_path=state_path,
            events_path=events_path,
            continued=continued,
            platform=platform,
        )

# Reasons that mean "this turn really ended" — the next user turn starts from
# zero. Everything else (a cap, a cooldown, an empty reply) must keep the chain
# open: resetting there let 8 identical stop events produce 6 nudges with
# max_nudges_per_turn: 2.
CLOSING_REASONS = frozenset({"no_trigger", "boundary", "user_must"})

def _cap_reason(
    cfg: dict[str, Any],
    *,
    attempt: int,
    total: int,
    chain_open: bool,
    last_ts: float,
    now: float,
) -> str | None:
    """Which cap (if any) stops this nudge. Pure: no state, no clock, no I/O.

    Returns the reason code, or None when the nudge may go ahead.
    """
    if chain_open:
        max_per_turn = int(_num(cfg.get("max_nudges_per_turn", 2), 2, integer=True))
        if attempt >= max_per_turn:
            return "max_nudges"
    max_per_session = int(_num(cfg.get("max_nudges_per_session", 20), 20, integer=True))
    if total >= max_per_session:
        return "max_nudges_per_session"
    cooldown = _num(cfg.get("cooldown_seconds", 0) or 0, 0, integer=False)
    if cooldown > 0 and total > 0 and now - last_ts < cooldown:
        return "cooldown"
    return None

def _record_outcome(
    entry: dict[str, Any],
    *,
    state: dict[str, Any],
    state_path: Path,
    nudge: bool,
    reason: str,
    attempt: int,
    total: int,
    now: float,
) -> None:
    """Update the session's counters and persist the state file."""
    if nudge:
        entry["count"] = attempt + 1
        entry["total"] = total + 1
        entry["last_ts"] = now
        entry["chain"] = True
    elif reason in CLOSING_REASONS:
        # The turn ended without a nudge — close the chain.
        entry["count"] = 0
        entry["chain"] = False
    # else: leave the chain (and the per-turn counter) exactly as it was.
    state["version"] = STATE_VERSION
    write_state(state, state_path)

def _decide_locked(
    text: str,
    *,
    session_id: str,
    host: str,
    cfg: dict[str, Any],
    state_path: Path,
    events_path: Path | str | None,
    continued: bool,
    platform: str,
) -> Decision:
    """The decision itself. Callers hold the state lock."""
    state = read_state(state_path)
    now = time.time()
    _prune_sessions(state, now)
    entry = _session_entry(state, session_id)
    chain_open = bool(entry.get("chain")) or continued
    if not chain_open:
        # A fresh turn: the per-turn counter starts from zero.
        entry["count"] = 0

    attempt = int(_num(entry.get("count", 0), 0, integer=True))
    total = int(_num(entry.get("total", 0), 0, integer=True))
    snippet = (text or "")[-160:]

    def finish(nudge: bool, reason: str) -> Decision:
        _record_outcome(
            entry,
            state=state,
            state_path=state_path,
            nudge=nudge,
            reason=reason,
            attempt=attempt,
            total=total,
            now=now,
        )
        log_event(
            {
                "session": session_id,
                "host": host,
                "platform": platform,
                "decision": ("nudge" if nudge else "skip")
                + ("_dryrun" if cfg.get("dry_run") else ""),
                "reason": reason,
                "attempt": attempt,
                "snippet": snippet,
            },
            events_path,
            snippet=bool(cfg.get("log_snippet", True)),
        )
        return Decision(should_nudge=nudge, reason=reason, attempt=attempt)

    if not cfg.get("enabled", True):
        return finish(False, "disabled")
    if not text or not text.strip():
        return finish(False, "empty")

    try:
        should, reason = detect(text, attempt, cfg)
    except Exception as exc:  # detection must never break a turn
        return finish(False, f"error:{type(exc).__name__}")

    # Judge the text *before* the caps. A clean end of turn has to close the
    # chain even when the per-turn cap is already reached, or the chain stays
    # open forever and that session never nudges again — which is what checking
    # the cap first did to hermes / opencode / pi / dsh / cursor.
    if reason in CLOSING_REASONS:
        return finish(False, reason)

    capped = _cap_reason(
        cfg,
        attempt=attempt,
        total=total,
        chain_open=chain_open,
        last_ts=_num(entry.get("last_ts", 0.0), 0.0, integer=False),
        now=now,
    )
    if capped:
        return finish(False, capped)

    if cfg.get("dry_run"):
        return finish(False, "dry_run")
    return finish(bool(should), reason)

# ── the Hermes core seam ────────────────────────────────────────────────────
def continue_hook_enabled() -> bool:
    """Is the core gate switched on?

    ``agent.continue_hook_enabled`` is the documented switch, and it defaults
    to **off** — installing the patch must not start nudging turns behind the
    user's back. The earlier version fell through to the shared config's
    ``enabled`` (default true), so the switch did nothing and the gate ran as
    soon as it was installed.
    """
    switch = None
    try:
        from hermes_cli.config import load_config

        switch = (load_config().get("agent") or {}).get("continue_hook_enabled")
    except Exception:
        switch = None
    if switch is None:
        # Nothing configured (a fresh install, a test, a bare import): the gate
        # stays off rather than guessing. HERMES_CONTINUE_HOOK=1 is the
        # explicit opt-in; HERMES_CONTINUE_HOOK=0 is the kill switch below.
        return os.environ.get("HERMES_CONTINUE_HOOK") == "1"
    return bool(switch)

def continue_hook_nudge(agent, final_response) -> str | None:
    """The stop-gate entry point. Called by ``turn_stop_gates.apply_stop_gates``.

    Returns the nudge text to feed back into the turn, or ``None`` to let the
    turn end. Every failure is silent: a broken gate must not break the loop.
    """
    try:
        if os.environ.get("HERMES_CONTINUE_HOOK") == "0":
            return None
        if not continue_hook_enabled():
            return None
        session_id = str(getattr(agent, "session_id", "") or "hermes")
        platform = str(getattr(agent, "platform", "") or "")
        attempt = int(getattr(agent, "_continue_hook_nudges", 0) or 0)
        decision = decide(str(final_response or ""), session_id=session_id,
                          host="hermes-patch", platform=platform)
        if not decision.should_nudge:
            return None
        agent._continue_hook_nudges = attempt + 1
        return build_nudge(decision.attempt, decision.reason)
    except Exception:
        return None
